import"./chunk-VC46IEJQ.js";var o=(e,t)=>({ref:"agot",checked:"memory",note:{en:e,zh:t}}),a={id:"kings-landing",intro:{en:"The capital of the Seven Kingdoms spreads over three hills on the north bank of the Blackwater Rush, where the river meets Blackwater Bay. The Red Keep crowns Aegon's High Hill above the harbour; the Great Sept of Baelor and the Dragonpit stand on the other two. The books name hills, gates and districts but give no street plan, so this is a reconstruction.",zh:"\u4E03\u5927\u738B\u56FD\u7684\u90FD\u57CE\u5750\u843D\u5728\u9ED1\u6C34\u6CB3\u5317\u5CB8\u7684\u4E09\u5EA7\u5C71\u4E18\u4E0A\uFF0C\u6FD2\u4E34\u9ED1\u6C34\u6CB3\u6CE8\u5165\u9ED1\u6C34\u6E7E\u4E4B\u5904\u3002\u7EA2\u5821\u96C4\u8E1E\u4F0A\u803F\u9AD8\u4E18\uFF0C\u4FEF\u77B0\u6E2F\u53E3\uFF1B\u8D1D\u52D2\u5927\u5723\u5802\u4E0E\u9F99\u7A74\u5206\u636E\u53E6\u5916\u4E24\u4E18\u3002\u4E66\u4E2D\u70B9\u660E\u4E86\u5C71\u4E18\u3001\u57CE\u95E8\u4E0E\u8857\u533A\uFF0C\u5374\u4ECE\u672A\u7ED9\u51FA\u8857\u9053\u5E73\u9762\uFF0C\u56E0\u6B64\u672C\u573A\u666F\u5C5E\u4E8E\u91CD\u6784\u3002"},notes:{en:"From the books: three hills with the Red Keep, the Great Sept of Baelor and the Dragonpit; the Blackwater Rush and the bay; a walled city with seven named gates; Flea Bottom, the Street of Steel and the Street of the Sisters; Maegor's Holdfast with its spiked dry moat; the Tower of the Hand; the Iron Throne in the throne room; Traitor's Walk in the dungeons. Invented: the street plan, gate positions, building shapes, the harbour and the throne-room interior.",zh:"\u4E66\u4E2D\u786E\u7ACB\uFF1A\u4E09\u5EA7\u5C71\u4E18\u53CA\u5176\u4E0A\u7684\u7EA2\u5821\u3001\u8D1D\u52D2\u5927\u5723\u5802\u4E0E\u9F99\u7A74\uFF1B\u9ED1\u6C34\u6CB3\u4E0E\u9ED1\u6C34\u6E7E\uFF1B\u6709\u4E03\u5EA7\u5177\u540D\u57CE\u95E8\u7684\u57CE\u5899\uFF1B\u8DF3\u86A4\u7A9D\u3001\u94A2\u94C1\u8857\u4E0E\u59D0\u59B9\u8857\uFF1B\u5916\u7ED5\u5C16\u523A\u5E72\u58D5\u7684\u6885\u845B\u697C\uFF1B\u9996\u76F8\u5854\uFF1B\u738B\u5EA7\u5385\u4E2D\u7684\u94C1\u738B\u5EA7\uFF1B\u5730\u7262\u4E2D\u7684\u53DB\u5F92\u8D70\u9053\u3002\u81EA\u884C\u8BBE\u8BA1\uFF1A\u8857\u9053\u5E73\u9762\u3001\u57CE\u95E8\u4F4D\u7F6E\u3001\u5EFA\u7B51\u9020\u578B\u3001\u6E2F\u53E3\u5E03\u5C40\u53CA\u738B\u5EA7\u5385\u5185\u90E8\u3002"},tour:["harbor","blackwater-rush","red-keep","maegors-holdfast","hands-tower","iron-throne-hall","traitors-walk","great-sept-of-baelor","street-of-steel","flea-bottom","dragonpit","city-walls-and-gates"],sources:[o("The city appears in every novel; Eddard, Arya, Sansa, Tyrion and Cersei chapters supply most details. Recalled, not re-read.","\u541B\u4E34\u5728\u6BCF\u4E00\u5377\u4E2D\u90FD\u6709\u51FA\u573A\uFF0C\u5927\u90E8\u5206\u7EC6\u8282\u6765\u81EA\u827E\u5FB7\u3001\u827E\u8389\u4E9A\u3001\u73CA\u838E\u3001\u63D0\u5229\u6602\u4E0E\u745F\u66E6\u7684\u7AE0\u8282\u3002\u51ED\u8BB0\u5FC6\uFF0C\u672A\u91CD\u8BFB\u3002"),{ref:"awoiaf",checked:"search-snippet",note:{en:`Search summaries of the wiki and the Westeros.org concordance were used to check the seven gates, the spiked moat of Maegor's Holdfast, the Red Keep's "seven huge drum-towers", Traitor's Walk and the route of the Street of the Sisters. Pages not fetched.`,zh:"\u501F\u52A9\u7EF4\u57FA\u4E0E Westeros.org \u8BCD\u6761\u7D22\u5F15\u7684\u641C\u7D22\u6458\u8981\uFF0C\u6838\u5BF9\u4E86\u4E03\u5EA7\u57CE\u95E8\u3001\u6885\u845B\u697C\u7684\u5C16\u523A\u5E72\u58D5\u3001\u7EA2\u5821\u7684\u201C\u4E03\u5EA7\u5DE8\u5927\u5706\u5854\u201D\u3001\u53DB\u5F92\u8D70\u9053\u4EE5\u53CA\u59D0\u59B9\u8857\u7684\u8D70\u5411\u3002\u9875\u9762\u672A\u6293\u53D6\u3002"}},{ref:"twoiaf",checked:"memory",note:{en:"The building history of the Red Keep, the Great Sept and the Dragonpit. Recalled.",zh:"\u7EA2\u5821\u3001\u8D1D\u52D2\u5927\u5723\u5802\u4E0E\u9F99\u7A74\u7684\u8425\u5EFA\u53F2\u3002\u51ED\u8BB0\u5FC6\u3002"}},{ref:"maps",checked:"not-accessed",note:{en:"Official city maps were not available; gate and hill positions follow a general recollection of the published map and are approximate.",zh:"\u672A\u80FD\u67E5\u9605\u5B98\u65B9\u57CE\u5E02\u5730\u56FE\uFF1B\u57CE\u95E8\u4E0E\u5C71\u4E18\u7684\u4F4D\u7F6E\u51ED\u5BF9\u5DF2\u51FA\u7248\u5730\u56FE\u7684\u5927\u81F4\u5370\u8C61\uFF0C\u4EC5\u4E3A\u8FD1\u4F3C\u3002"}}],landmarks:{"red-keep":{name:{en:"Red Keep",zh:"\u7EA2\u5821"},desc:{en:"The royal castle on Aegon's High Hill: pale red stone, great drum towers, barbican and curtain walls above the city.",zh:"\u4F0A\u803F\u9AD8\u4E18\u4E0A\u7684\u738B\u5BB6\u57CE\u5821\uFF1A\u6DE1\u7EA2\u8272\u77F3\u6750\uFF0C\u5DE8\u5927\u7684\u5706\u5854\u3001\u57CE\u95E8\u5821\u4E0E\u5E55\u5899\u9AD8\u8E1E\u5168\u57CE\u4E4B\u4E0A\u3002"},tour:{en:"The Red Keep crowns Aegon's High Hill: red stone, drum towers and the seat of the realm.",zh:"\u7EA2\u5821\u96C4\u8E1E\u4F0A\u803F\u9AD8\u4E18\uFF1A\u7EA2\u77F3\u57CE\u5899\u3001\u5DE8\u5927\u5706\u5854\uFF0C\u662F\u738B\u56FD\u6743\u529B\u7684\u4E2D\u67A2\u3002"},spoiler:{en:"Its secret passages matter greatly in later books.",zh:"\u57CE\u4E2D\u7684\u5BC6\u9053\u5728\u540E\u7EED\u5404\u5377\u4E2D\u4E3E\u8DB3\u8F7B\u91CD\u3002"},source:{confidence:"high",refs:["agot","twoiaf","awoiaf"],book:{en:"A castle of pale red stone on Aegon's High Hill, described with seven huge drum towers, a barbican, covered bridges and massive curtain walls. Begun by Aegon I and completed under Maegor I (companion).",zh:"\u4F0A\u803F\u9AD8\u4E18\u4E0A\u7684\u6DE1\u7EA2\u77F3\u57CE\u5821\uFF0C\u4E66\u4E2D\u63CF\u5199\u5176\u6709\u4E03\u5EA7\u5DE8\u5927\u5706\u5854\u3001\u57CE\u95E8\u5821\u3001\u5ECA\u6865\u4E0E\u539A\u91CD\u5E55\u5899\u3002\u59CB\u5EFA\u4E8E\u4F0A\u803F\u4E00\u4E16\uFF0C\u5B8C\u5DE5\u4E8E\u6885\u845B\u4E00\u4E16\uFF08\u636E\u8BBE\u5B9A\u96C6\uFF09\u3002"},unknown:{en:"Floor plan, wall circuit and where each tower stands.",zh:"\u5E73\u9762\u5E03\u5C40\u3001\u57CE\u5899\u8D70\u5411\uFF0C\u4EE5\u53CA\u5404\u5854\u7684\u5177\u4F53\u4F4D\u7F6E\u3002"},interpretation:{en:"A ring of towered curtain walls around a plateau; tower positions and halls are invented.",zh:"\u9AD8\u5730\u56DB\u5468\u73AF\u7ED5\u5E26\u5854\u697C\u7684\u5E55\u5899\uFF1B\u5854\u697C\u4E0E\u5385\u5802\u7684\u4F4D\u7F6E\u5747\u4E3A\u81EA\u62DF\u3002"}}},"maegors-holdfast":{name:{en:"Maegor's Holdfast",zh:"\u6885\u845B\u697C"},desc:{en:"A castle within the castle: a massive square keep behind a dry moat lined with iron spikes, crossed by a single drawbridge.",zh:"\u5821\u4E2D\u4E4B\u5821\uFF1A\u4E00\u5EA7\u539A\u91CD\u7684\u65B9\u5F62\u5821\u697C\uFF0C\u5916\u7ED5\u904D\u5E03\u94C1\u523A\u7684\u5E72\u58D5\uFF0C\u53EA\u6709\u4E00\u5EA7\u540A\u6865\u53EF\u901A\u3002"},tour:{en:"Maegor's Holdfast: a dry moat of spikes, one drawbridge, and the royal apartments within.",zh:"\u6885\u845B\u697C\uFF1A\u6EE1\u5E03\u94C1\u523A\u7684\u5E72\u58D5\uFF0C\u552F\u4E00\u7684\u540A\u6865\uFF0C\u738B\u5BA4\u5BDD\u5C45\u5C31\u5728\u5176\u5185\u3002"},source:{confidence:"high",refs:["agot","acok","awoiaf"],book:{en:"A square fortress inside the Red Keep with thick walls and a dry moat lined with iron spikes, crossed by a drawbridge; the royal family lives inside.",zh:"\u7EA2\u5821\u5185\u7684\u65B9\u5F62\u8981\u585E\uFF0C\u5899\u4F53\u539A\u91CD\uFF0C\u5916\u6709\u5E03\u6EE1\u94C1\u523A\u7684\u5E72\u58D5\uFF0C\u4EE5\u540A\u6865\u51FA\u5165\uFF1B\u738B\u5BA4\u6210\u5458\u5C45\u4F4F\u5176\u4E2D\u3002"},unknown:{en:"Its towers and exact dimensions.",zh:"\u5854\u697C\u60C5\u51B5\u4E0E\u786E\u5207\u5C3A\u5BF8\u3002"},interpretation:{en:'The scene rings it with seven drum towers. The novels give "seven drum-towers" to the Red Keep as a whole, not to the holdfast, so this is a deliberate transfer.',zh:"\u672C\u573A\u666F\u4E3A\u6885\u845B\u697C\u914D\u4E86\u4E03\u5EA7\u5706\u5854\u3002\u4E66\u4E2D\u7684\u201C\u4E03\u5EA7\u5706\u5854\u201D\u6307\u6574\u5EA7\u7EA2\u5821\u800C\u975E\u6885\u845B\u697C\uFF0C\u8FD9\u91CC\u662F\u6709\u610F\u7684\u632A\u7528\u3002"}}},"hands-tower":{name:{en:"Tower of the Hand",zh:"\u9996\u76F8\u5854"},desc:{en:"The tower where the Hand of the King lives and works, with his solar and a view over the city.",zh:"\u56FD\u738B\u4E4B\u624B\u8D77\u5C45\u4E0E\u7406\u653F\u7684\u5854\u697C\uFF0C\u5185\u8BBE\u4E66\u623F\uFF0C\u53EF\u4FEF\u77B0\u5168\u57CE\u3002"},tour:{en:"The Tower of the Hand: home and office of the king's chief minister.",zh:"\u9996\u76F8\u5854\uFF1A\u56FD\u738B\u9996\u5E2D\u91CD\u81E3\u7684\u5C45\u6240\u4E0E\u5B98\u7F72\u3002"},source:{confidence:"high",refs:["agot","acok"],book:{en:"The Hand lives in the Tower of the Hand; both Eddard and Tyrion use its solar.",zh:"\u56FD\u738B\u4E4B\u624B\u4F4F\u5728\u9996\u76F8\u5854\uFF1B\u827E\u5FB7\u4E0E\u63D0\u5229\u6602\u90FD\u66FE\u5728\u5854\u4E2D\u4E66\u623F\u7406\u4E8B\u3002"},unknown:{en:"Its position in the keep, height and shape.",zh:"\u5728\u7EA2\u5821\u4E2D\u7684\u4F4D\u7F6E\u3001\u9AD8\u5EA6\u4E0E\u5916\u5F62\u3002"},interpretation:{en:"A slim, tall round tower on the south-west side, taller than its neighbours.",zh:"\u897F\u5357\u4FA7\u7684\u4E00\u5EA7\u7EC6\u9AD8\u5706\u5854\uFF0C\u9AD8\u51FA\u5468\u56F4\u5404\u5854\u3002"}}},"iron-throne-hall":{name:{en:"Throne Room",zh:"\u738B\u5EA7\u5385"},desc:{en:"The great hall where the king sits the Iron Throne, a jagged seat of swords atop steep iron steps. A cutaway shows the interior.",zh:"\u56FD\u738B\u5750\u4E0A\u94C1\u738B\u5EA7\u7684\u5927\u5385\uFF1A\u65E0\u6570\u5251\u5203\u94F8\u6210\u7684\u5D99\u5CCB\u738B\u5EA7\uFF0C\u9AD8\u8E1E\u9661\u5CED\u7684\u94C1\u9636\u4E4B\u4E0A\u3002\u53EF\u8FDB\u5165\u5256\u9762\u67E5\u770B\u5185\u90E8\u3002"},tour:{en:"A thousand swords forged into one jagged seat, set high so that all must look up.",zh:"\u5343\u5251\u7194\u94F8\u6210\u4E00\u5F20\u5D99\u5CCB\u738B\u5EA7\uFF0C\u9AD8\u9AD8\u5728\u4E0A\uFF0C\u4EE4\u6EE1\u671D\u4EF0\u89C6\u3002"},spoiler:{en:"Who sits the throne changes more than once in later books.",zh:"\u94C1\u738B\u5EA7\u7684\u4E3B\u4EBA\u5728\u540E\u7EED\u5404\u5377\u4E2D\u6570\u5EA6\u6613\u624B\u3002"},source:{confidence:"high",refs:["agot","acok"],book:{en:"A long, high throne room with tall windows; the Iron Throne, a mass of swords with jagged edges, stands atop steep iron steps. The Targaryen dragon skulls once hung here.",zh:"\u9AD8\u655E\u72ED\u957F\u7684\u738B\u5EA7\u5385\uFF0C\u5F00\u6709\u9AD8\u7A97\uFF1B\u94C1\u738B\u5EA7\u7531\u5251\u5203\u7194\u94F8\uFF0C\u8FB9\u7F18\u53C2\u5DEE\uFF0C\u7ACB\u4E8E\u9661\u5CED\u7684\u94C1\u9636\u9876\u7AEF\u3002\u5766\u683C\u5229\u5B89\u5BB6\u7684\u9F99\u5934\u9AA8\u6614\u65E5\u66FE\u60AC\u6302\u4E8E\u6B64\u3002"},unknown:{en:"Hall dimensions, columns and decoration.",zh:"\u5927\u5385\u5C3A\u5BF8\u3001\u7ACB\u67F1\u4E0E\u88C5\u9970\u3002"},interpretation:{en:"A pillared nave with clerestory windows, a red carpet, banners and fourteen steps; all proportions invented.",zh:"\u5E26\u9AD8\u4FA7\u7A97\u7684\u67F1\u5ECA\u957F\u5385\uFF0C\u94FA\u7EA2\u6BEF\u3001\u6302\u65D7\u5E1C\uFF0C\u8BBE\u5341\u56DB\u7EA7\u53F0\u9636\uFF1B\u6BD4\u4F8B\u5747\u4E3A\u81EA\u62DF\u3002"}}},"traitors-walk":{name:{en:"Traitor's Walk",zh:"\u53DB\u5F92\u8D70\u9053"},desc:{en:"In the novels, a passage in the Red Keep's dungeons leading to a squat half-round tower; the scene shows it as a riverside landing.",zh:"\u5728\u5C0F\u8BF4\u91CC\uFF0C\u8FD9\u662F\u7EA2\u5821\u5730\u7262\u4E2D\u901A\u5F80\u4E00\u5EA7\u77EE\u80D6\u534A\u5706\u5854\u7684\u901A\u9053\uFF1B\u672C\u573A\u666F\u5219\u628A\u5B83\u8868\u73B0\u4E3A\u4E34\u6CB3\u7684\u767B\u5CB8\u5904\u3002"},tour:{en:"Arya stumbles on Traitor's Walk in the dungeons; our riverside version is invented.",zh:"\u827E\u8389\u4E9A\u66FE\u5728\u5730\u7262\u4E2D\u8BEF\u5165\u53DB\u5F92\u8D70\u9053\uFF1B\u573A\u666F\u4E2D\u7684\u4E34\u6CB3\u7248\u672C\u7CFB\u865A\u6784\u3002"},source:{confidence:"low",refs:["agot","affc","awoiaf"],book:{en:"Traitor's Walk is a passage in the dungeons leading to a squat, half-round tower; Arya finds it while lost chasing a cat, and Jaime passes it in A Feast for Crows.",zh:"\u53DB\u5F92\u8D70\u9053\u662F\u5730\u7262\u4E2D\u901A\u5F80\u4E00\u5EA7\u77EE\u80D6\u534A\u5706\u5854\u7684\u901A\u9053\uFF1B\u827E\u8389\u4E9A\u8FFD\u732B\u8FF7\u8DEF\u65F6\u649E\u89C1\u6B64\u5904\uFF0C\u8A79\u59C6\u5728\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u4E2D\u4E5F\u66FE\u7ECF\u8FC7\u3002"},unknown:{en:"Its exact place in the keep and its appearance.",zh:"\u5728\u7EA2\u5821\u4E2D\u7684\u786E\u5207\u4F4D\u7F6E\u4E0E\u6837\u8C8C\u3002"},interpretation:{en:"The model is a landing stage and stair on the river side of the hill. This does not match the novels (an earlier draft wrongly called it a water gate); treat the model as invention.",zh:"\u6A21\u578B\u4E3A\u5C71\u4E18\u4E34\u6CB3\u4E00\u4FA7\u7684\u7801\u5934\u4E0E\u77F3\u9636\uFF0C\u4E0E\u5C0F\u8BF4\u4E0D\u7B26\uFF08\u65E9\u5148\u7684\u6587\u672C\u8BEF\u79F0\u5176\u4E3A\u6C34\u95E8\uFF09\uFF1B\u8BF7\u89C6\u4F5C\u865A\u6784\u3002"}}},"great-sept-of-baelor":{name:{en:"Great Sept of Baelor",zh:"\u8D1D\u52D2\u5927\u5723\u5802"},desc:{en:"The seat of the Faith of the Seven on Visenya's Hill: white marble beneath a great dome, with seven crystal towers.",zh:"\u4E03\u795E\u4FE1\u4EF0\u7684\u4E2D\u5FC3\uFF0C\u5750\u843D\u4E8E\u7EF4\u6851\u5C3C\u4E9A\u4E18\uFF1A\u767D\u8272\u5927\u7406\u77F3\u6BBF\u5B87\uFF0C\u4E0A\u8986\u5DE8\u5927\u7A79\u9876\uFF0C\u4E03\u5EA7\u6C34\u6676\u5854\u73AF\u7ACB\u3002"},tour:{en:"Marble, a great dome and seven crystal towers on Visenya's Hill: the High Septon's seat.",zh:"\u7EF4\u6851\u5C3C\u4E9A\u4E18\u4E0A\u7684\u5927\u7406\u77F3\u6BBF\u5B87\u3001\u5DE8\u5927\u7A79\u9876\u4E0E\u4E03\u5EA7\u6C34\u6676\u5854\uFF1A\u5927\u4E3B\u6559\u9A7B\u9521\u4E4B\u6240\u3002"},spoiler:{en:"Its steps are the scene of a famous execution in the first book.",zh:"\u7B2C\u4E00\u5377\u4E2D\u4E00\u573A\u8457\u540D\u7684\u5904\u51B3\u5C31\u53D1\u751F\u5728\u5B83\u7684\u53F0\u9636\u4E0A\u3002"},source:{confidence:"high",refs:["agot","acok","twoiaf"],book:{en:"Named for Baelor the Blessed, on Visenya's Hill, of marble with a dome and seven crystal towers; a statue of Baelor stands in the plaza before it.",zh:"\u4EE5\u201C\u53D7\u795E\u795D\u798F\u7684\u201D\u8D1D\u52D2\u547D\u540D\uFF0C\u4F4D\u4E8E\u7EF4\u6851\u5C3C\u4E9A\u4E18\uFF0C\u5927\u7406\u77F3\u5EFA\u6210\uFF0C\u6709\u7A79\u9876\u4E0E\u4E03\u5EA7\u6C34\u6676\u5854\uFF1B\u95E8\u524D\u5E7F\u573A\u4E0A\u7ACB\u7740\u8D1D\u52D2\u7684\u96D5\u50CF\u3002"},unknown:{en:"Interior layout, tower heights and arrangement.",zh:"\u5185\u90E8\u5E03\u5C40\u3001\u5854\u9AD8\u4E0E\u4E03\u5854\u7684\u6392\u5E03\u3002"},interpretation:{en:"A domed round body ringed by seven glass-roofed towers, plus two low annexes.",zh:"\u5706\u5F62\u7A79\u9876\u4E3B\u4F53\uFF0C\u5916\u73AF\u4E03\u5EA7\u73BB\u7483\u9876\u5854\uFF0C\u53E6\u6709\u4E24\u5EA7\u4F4E\u77EE\u4FA7\u6BBF\u3002"}}},dragonpit:{name:{en:"Dragonpit",zh:"\u9F99\u7A74"},desc:{en:"The vast domed hall on Rhaenys's Hill that once housed the Targaryen dragons, now a ruin with its dome fallen in.",zh:"\u96F7\u59AE\u4E1D\u4E18\u4E0A\u7684\u5DE8\u5927\u7A79\u9876\u5EFA\u7B51\uFF0C\u6614\u65E5\u8C62\u517B\u5766\u683C\u5229\u5B89\u5BB6\u65CF\u7684\u9F99\uFF0C\u5982\u4ECA\u7A79\u9876\u574D\u584C\uFF0C\u53EA\u5269\u5E9F\u589F\u3002"},tour:{en:"Once a house for dragons, now an empty ruin with great bronze doors.",zh:"\u6614\u65E5\u7684\u9F99\u4E4B\u5C45\u6240\uFF0C\u5982\u4ECA\u53EA\u5269\u5DE8\u5927\u7684\u9752\u94DC\u95E8\u4E0E\u4E00\u7247\u5E9F\u589F\u3002"},source:{confidence:"high",refs:["agot","acok","twoiaf"],book:{en:"A great ruined dome on Rhaenys's Hill with huge bronze doors; it has stood empty since the last dragons died, and its dome has collapsed.",zh:"\u96F7\u59AE\u4E1D\u4E18\u4E0A\u7684\u5DE8\u5927\u6B8B\u7834\u7A79\u9876\uFF0C\u6709\u5DE8\u578B\u9752\u94DC\u95E8\uFF1B\u81EA\u6700\u540E\u7684\u9F99\u6B7B\u53BB\u540E\u4FBF\u4E00\u76F4\u7A7A\u7F6E\uFF0C\u7A79\u9876\u4E5F\u5DF2\u574D\u584C\u3002"},unknown:{en:"Number of doors, diameter and the shape of the ruin.",zh:"\u95E8\u7684\u6570\u91CF\u3001\u76F4\u5F84\u4E0E\u5E9F\u589F\u5F62\u6001\u3002"},interpretation:{en:"A ring of broken wall with ribs of the fallen dome on one side.",zh:"\u4E00\u5708\u6B8B\u7834\u7684\u5899\u57A3\uFF0C\u4E00\u4FA7\u7559\u7740\u574D\u843D\u7A79\u9876\u7684\u62F1\u808B\u3002"}}},"flea-bottom":{name:{en:"Flea Bottom",zh:"\u8DF3\u86A4\u7A9D"},desc:{en:"The poorest, most crowded quarter, a low maze of hovels, pot-shops and taverns between the hills.",zh:"\u57CE\u4E2D\u6700\u7A77\u4E5F\u6700\u62E5\u6324\u7684\u8857\u533A\uFF1A\u5C71\u4E18\u4E4B\u95F4\u7684\u4F4E\u6D3C\u5730\u5E26\uFF0C\u7834\u5C4B\u3001\u6C64\u94FA\u4E0E\u9152\u9986\u6324\u6210\u4E00\u7247\u8FF7\u5BAB\u3002"},tour:{en:"Low, crowded and pungent: Flea Bottom, famous for its bowls of brown.",zh:"\u4F4E\u6D3C\u3001\u62E5\u6324\u3001\u6C14\u5473\u523A\u9F3B\uFF1A\u8FD9\u5C31\u662F\u4EE5\u8857\u8FB9\u7096\u83DC\u95FB\u540D\u7684\u8DF3\u86A4\u7A9D\u3002"},source:{confidence:"high",refs:["agot","acok"],book:{en:`The city's squalid, crowded slum, known for its pot-shops and their stew ("bowl of brown").`,zh:"\u57CE\u4E2D\u80AE\u810F\u62E5\u6324\u7684\u8D2B\u6C11\u7A9F\uFF0C\u4EE5\u6C64\u94FA\u548C\u90A3\u91CC\u7684\u6742\u70E9\u7096\u83DC\u95FB\u540D\u3002"},unknown:{en:"Exact boundaries and street layout.",zh:"\u786E\u5207\u8FB9\u754C\u4E0E\u8857\u9053\u5E03\u5C40\u3002"},interpretation:{en:"A low basin of small timber houses with market awnings east of the Mud Gate road.",zh:"\u6CE5\u95E8\u5927\u8DEF\u4EE5\u4E1C\u7684\u4E00\u7247\u6D3C\u5730\uFF0C\u5C0F\u6728\u5C4B\u4E0E\u644A\u68DA\u5BC6\u5E03\u3002"}}},"street-of-steel":{name:{en:"Street of Steel",zh:"\u94A2\u94C1\u8857"},desc:{en:"The street of armourers and smiths, ringing with hammers and hazy with forge smoke.",zh:"\u519B\u68B0\u5320\u4E0E\u94C1\u5320\u805A\u5C45\u7684\u8857\u9053\uFF0C\u9524\u58F0\u53EE\u5F53\uFF0C\u7089\u70DF\u5F25\u6F2B\u3002"},tour:{en:"Armourers and smiths line the Street of Steel; Tobho Mott keeps his shop here.",zh:"\u94A2\u94C1\u8857\u4E24\u65C1\u5C3D\u662F\u519B\u68B0\u5320\u4E0E\u94C1\u5320\uFF0C\u6258\u52C3\xB7\u83AB\u7279\u7684\u94FA\u5B50\u5C31\u5F00\u5728\u8FD9\u91CC\u3002"},source:{confidence:"high",refs:["agot","acok"],book:{en:"The armourers' and weaponsmiths' street, which climbs Visenya's Hill; Eddard visits Tobho Mott's forge there.",zh:"\u519B\u68B0\u5320\u4E0E\u5175\u5668\u5320\u805A\u5C45\u7684\u8857\u9053\uFF0C\u6CBF\u7EF4\u6851\u5C3C\u4E9A\u4E18\u800C\u4E0A\uFF1B\u827E\u5FB7\u66FE\u5230\u6B64\u9020\u8BBF\u6258\u52C3\xB7\u83AB\u7279\u7684\u94C1\u94FA\u3002"},unknown:{en:"Its full route and connections to the gates.",zh:"\u5B8C\u6574\u8D70\u5411\u53CA\u4E0E\u5404\u57CE\u95E8\u7684\u8FDE\u63A5\u3002"},interpretation:{en:"Placed along a south-west road toward the Red Keep and shown with forge smoke; the novels put it on Visenya's Hill instead.",zh:"\u7F6E\u4E8E\u901A\u5F80\u7EA2\u5821\u7684\u897F\u5357\u9053\u8DEF\u65C1\uFF0C\u4EE5\u7089\u70DF\u8868\u73B0\uFF1B\u5C0F\u8BF4\u5219\u5C06\u5B83\u7F6E\u4E8E\u7EF4\u6851\u5C3C\u4E9A\u4E18\u3002"}}},"street-of-sisters":{name:{en:"Street of the Sisters",zh:"\u59D0\u59B9\u8857"},desc:{en:"A broad street named for Aegon's sister-wives, linking Visenya's Hill and Rhaenys's Hill.",zh:"\u4EE5\u4F0A\u803F\u7684\u4E24\u4F4D\u59D0\u59B9\u517C\u59BB\u5B50\u547D\u540D\u7684\u5BBD\u9614\u8857\u9053\uFF0C\u8FDE\u63A5\u7EF4\u6851\u5C3C\u4E9A\u4E18\u4E0E\u96F7\u59AE\u4E1D\u4E18\u3002"},tour:{en:"The Street of the Sisters runs between the hills of Visenya and Rhaenys.",zh:"\u59D0\u59B9\u8857\u8FDE\u901A\u7EF4\u6851\u5C3C\u4E9A\u4E18\u4E0E\u96F7\u59AE\u4E1D\u4E18\u3002"},source:{confidence:"medium",refs:["agot","awoiaf"],book:{en:"A straight street running between Visenya's Hill (the Great Sept) and Rhaenys's Hill (the Dragonpit), per wiki summaries of novel references.",zh:"\u636E\u7EF4\u57FA\u5BF9\u5C0F\u8BF4\u51FA\u5904\u7684\u6458\u8981\uFF0C\u8FD9\u662F\u4E00\u6761\u7B14\u76F4\u7684\u8857\u9053\uFF0C\u8FDE\u63A5\u7EF4\u6851\u5C3C\u4E9A\u4E18\uFF08\u8D1D\u52D2\u5927\u5723\u5802\uFF09\u4E0E\u96F7\u59AE\u4E1D\u4E18\uFF08\u9F99\u7A74\uFF09\u3002"},unknown:{en:"Its exact course and the buildings along it.",zh:"\u786E\u5207\u8D70\u5411\u53CA\u6CBF\u8857\u5EFA\u7B51\u3002"},interpretation:{en:"Drawn as a wide road running north from the Sept's plaza to the Gate of the Gods. This route is invented and does not follow the books.",zh:"\u7ED8\u4F5C\u4E00\u6761\u81EA\u5723\u5802\u5E7F\u573A\u5411\u5317\u76F4\u62B5\u8BF8\u795E\u95E8\u7684\u5927\u8DEF\u3002\u6B64\u8D70\u5411\u4E3A\u81EA\u62DF\uFF0C\u4E0E\u4E66\u4E2D\u4E0D\u7B26\u3002"}}},harbor:{name:{en:"Harbour",zh:"\u6E2F\u53E3"},desc:{en:"Quays, piers and warehouses on Blackwater Bay, crowded with merchant ships and galleys from across the Narrow Sea.",zh:"\u9ED1\u6C34\u6E7E\u7554\u7684\u7801\u5934\u3001\u6808\u6865\u4E0E\u8D27\u6808\uFF0C\u6324\u6EE1\u6765\u81EA\u72ED\u6D77\u5BF9\u5CB8\u7684\u5546\u8239\u4E0E\u6868\u5E06\u8239\u3002"},tour:{en:"Cogs, galleys and traders crowd the quays on Blackwater Bay.",zh:"\u67EF\u514B\u8239\u3001\u6868\u5E06\u8239\u4E0E\u5546\u8239\u6324\u6EE1\u9ED1\u6C34\u6E7E\u7554\u7684\u7801\u5934\u3002"},spoiler:{en:"Blackwater Bay is the setting of a great battle in the second book.",zh:"\u9ED1\u6C34\u6E7E\u662F\u7B2C\u4E8C\u5377\u4E00\u573A\u5927\u6218\u7684\u6218\u573A\u3002"},source:{confidence:"medium",refs:["agot","acok"],book:{en:"A busy harbour on the river mouth and the bay, with quays, merchants and fishermen.",zh:"\u4F4D\u4E8E\u6CB3\u53E3\u4E0E\u6D77\u6E7E\u7684\u7E41\u5FD9\u6E2F\u53E3\uFF0C\u7801\u5934\u6797\u7ACB\uFF0C\u5546\u4EBA\u4E0E\u6E14\u6C11\u5F80\u6765\u3002"},unknown:{en:"Layout of piers and warehouses.",zh:"\u6808\u6865\u4E0E\u8D27\u6808\u7684\u5E03\u5C40\u3002"},interpretation:{en:"A stone quay, five piers, warehouses and cranes; the ships are generic cogs and galleys.",zh:"\u77F3\u780C\u7801\u5934\u3001\u4E94\u5EA7\u6808\u6865\u3001\u8D27\u6808\u4E0E\u540A\u673A\uFF1B\u8239\u53EA\u4E3A\u901A\u7528\u7684\u67EF\u514B\u8239\u4E0E\u6868\u5E06\u8239\u3002"}}},"blackwater-rush":{name:{en:"Blackwater Rush",zh:"\u9ED1\u6C34\u6CB3"},desc:{en:"The river that runs past the south of the city into Blackwater Bay, busy with barges and fishing boats.",zh:"\u6D41\u7ECF\u57CE\u5357\u3001\u6CE8\u5165\u9ED1\u6C34\u6E7E\u7684\u6CB3\u6D41\uFF0C\u9A73\u8239\u4E0E\u6E14\u8239\u5F80\u6765\u4E0D\u7EDD\u3002"},tour:{en:"The Rush bounds the city to the south; the Kingswood lies across the river.",zh:"\u9ED1\u6C34\u6CB3\u5212\u51FA\u90FD\u57CE\u7684\u5357\u754C\uFF0C\u5BF9\u5CB8\u4FBF\u662F\u5FA1\u6797\u3002"},source:{confidence:"high",refs:["agot","acok","maps"],book:{en:"The Blackwater Rush flows into Blackwater Bay beside the city, which stands on its north bank.",zh:"\u9ED1\u6C34\u6CB3\u5728\u57CE\u65C1\u6CE8\u5165\u9ED1\u6C34\u6E7E\uFF0C\u90FD\u57CE\u4F4D\u4E8E\u5176\u5317\u5CB8\u3002"},unknown:{en:"Exact width, bridges and docks.",zh:"\u786E\u5207\u6CB3\u5BBD\u3001\u6865\u6881\u4E0E\u7801\u5934\u3002"},interpretation:{en:"A broad river south of the walls; no bridge is shown.",zh:"\u57CE\u5899\u4EE5\u5357\u7684\u5BBD\u9614\u6CB3\u6D41\uFF1B\u672A\u8BBE\u6865\u6881\u3002"}}},"city-walls-and-gates":{name:{en:"Walls and Gates",zh:"\u57CE\u5899\u4E0E\u57CE\u95E8"},desc:{en:"A high wall pierced by seven gates: the Dragon Gate, Lion Gate, King's Gate, Old Gate, Gate of the Gods, Iron Gate and Mud Gate.",zh:"\u9AD8\u5927\u7684\u57CE\u5899\u5F00\u6709\u4E03\u95E8\uFF1A\u9F99\u95E8\u3001\u72EE\u95E8\u3001\u56FD\u738B\u95E8\u3001\u65E7\u95E8\u3001\u8BF8\u795E\u95E8\u3001\u94C1\u95E8\u4E0E\u6CE5\u95E8\u3002"},tour:{en:"Seven gates pierce the walls, each with its road and its guards.",zh:"\u57CE\u5899\u5F00\u6709\u4E03\u95E8\uFF0C\u5404\u6709\u9053\u8DEF\uFF0C\u5404\u6709\u5B88\u536B\u3002"},spoiler:{en:"Several gates are fought over in the second book.",zh:"\u7B2C\u4E8C\u5377\u4E2D\u6709\u51E0\u5EA7\u57CE\u95E8\u6210\u4E3A\u4E89\u593A\u7126\u70B9\u3002"},source:{confidence:"high",refs:["agot","acok","awoiaf"],book:{en:"A walled city with seven gates: Dragon Gate, Lion Gate, King's Gate, Old Gate, Gate of the Gods, Iron Gate and the Mud Gate (also called the River Gate).",zh:"\u90FD\u57CE\u6709\u57CE\u5899\u4E0E\u4E03\u5EA7\u57CE\u95E8\uFF1A\u9F99\u95E8\u3001\u72EE\u95E8\u3001\u56FD\u738B\u95E8\u3001\u65E7\u95E8\u3001\u8BF8\u795E\u95E8\u3001\u94C1\u95E8\uFF0C\u4EE5\u53CA\u6CE5\u95E8\uFF08\u53C8\u79F0\u6CB3\u95E8\uFF09\u3002"},unknown:{en:"Exact gate positions and the wall's height.",zh:"\u5404\u57CE\u95E8\u7684\u786E\u5207\u4F4D\u7F6E\u4E0E\u57CE\u5899\u9AD8\u5EA6\u3002"},interpretation:{en:"Gates are spaced around a polygonal wall that is open to the bay; positions are approximate.",zh:"\u5404\u57CE\u95E8\u5206\u5E03\u4E8E\u4E00\u9053\u591A\u8FB9\u5F62\u57CE\u5899\u4E0A\uFF0C\u4E34\u6E7E\u4E00\u4FA7\u655E\u5F00\uFF1B\u4F4D\u7F6E\u4EC5\u4E3A\u8FD1\u4F3C\u3002"}}},"mud-gate":{name:{en:"Mud Gate",zh:"\u6CE5\u95E8"},desc:{en:"The river gate near the fishmarket and the docks, officially the River Gate.",zh:"\u4E34\u6CB3\u7684\u57CE\u95E8\uFF0C\u9760\u8FD1\u9C7C\u5E02\u4E0E\u7801\u5934\uFF0C\u6B63\u5F0F\u540D\u79F0\u4E3A\u6CB3\u95E8\u3002"},tour:{en:"The Mud Gate opens onto the river docks below the city.",zh:"\u6CE5\u95E8\u671D\u5411\u57CE\u4E0B\u7684\u6CB3\u5CB8\u7801\u5934\u3002"},spoiler:{en:"It sees heavy fighting in the Battle of the Blackwater.",zh:"\u9ED1\u6C34\u6CB3\u4E4B\u6218\u4E2D\uFF0C\u6B64\u95E8\u7ECF\u5386\u4E86\u6FC0\u70C8\u7684\u6218\u6597\u3002"},source:{confidence:"medium",refs:["agot","acok","awoiaf"],book:{en:"The River Gate, commonly called the Mud Gate, faces the Blackwater Rush and its docks.",zh:"\u6CB3\u95E8\u4FD7\u79F0\u6CE5\u95E8\uFF0C\u9762\u5411\u9ED1\u6C34\u6CB3\u53CA\u6CB3\u8FB9\u7801\u5934\u3002"},unknown:{en:"Its exact position and appearance.",zh:"\u786E\u5207\u4F4D\u7F6E\u4E0E\u6837\u8C8C\u3002"},interpretation:{en:"A small gatehouse in a short river wall with a timber landing.",zh:"\u77ED\u77ED\u4E00\u6BB5\u4E34\u6CB3\u57CE\u5899\u4E0A\u7684\u5C0F\u57CE\u95E8\uFF0C\u914D\u6728\u8D28\u6808\u6865\u3002"}}}}};export{a as default};
